-- Kalkulator statystyk *pojedynczej broni*, niezależny od SQL034 i ashen_publish_profile.
-- Brak zmian w tabelach, brak migracji, brak włączenia jakości mitycznej.
-- Katalog generowany bezpośrednio z js/game.js; hash źródła jest zapisany w dokumentacji.
create or replace function public.ashen_060_weapon_preview_candidate(p_item jsonb)
returns jsonb language plpgsql immutable security invoker set search_path = '' as $$
declare
 c jsonb := '{"weapons":{"baton":{"min":5,"max":8,"attacks":1,"accuracy":2,"crit":0,"pen":0,"category":"Biała 1R","scale":0.72,"critMultiplier":2,"bonus":{},"name":"Pałka ochroniarza","slot":"hand1"},"pipe":{"min":6,"max":10,"attacks":1,"accuracy":-2,"crit":0,"pen":1,"category":"Biała 1R","scale":0.72,"critMultiplier":2,"bonus":{},"name":"Żelazna rura","slot":"weapon"},"wrench":{"min":7,"max":12,"attacks":1,"accuracy":2,"crit":0,"pen":0,"category":"Biała 1R","scale":0.72,"critMultiplier":2,"bonus":{},"name":"Klucz francuski","slot":"hand1"},"knife":{"min":6,"max":10,"attacks":2,"accuracy":4,"crit":3,"pen":0,"category":"Biała 1R","scale":0.72,"critMultiplier":2,"bonus":{},"name":"Zardzewiały nóż","slot":"weapon"},"cleaver":{"min":10,"max":16,"attacks":1,"accuracy":-3,"crit":5,"pen":0,"category":"Biała 1R","scale":0.72,"critMultiplier":2,"bonus":{},"name":"Tasak z pustkowi","slot":"weapon"},"hatchet":{"min":12,"max":18,"attacks":1,"accuracy":-2,"crit":2,"pen":2,"category":"Biała 1R","scale":0.72,"critMultiplier":2,"bonus":{},"name":"Toporek z odzysku","slot":"hand1"},"saber":{"min":10,"max":15,"attacks":2,"accuracy":1,"crit":2,"pen":0,"category":"Biała 1R","scale":0.72,"critMultiplier":2,"bonus":{},"name":"Szabla konwojenta","slot":"hand1"},"machete":{"min":12,"max":18,"attacks":2,"accuracy":-1,"crit":1,"pen":0,"category":"Biała 1R","scale":0.72,"critMultiplier":2,"bonus":{},"name":"Maczeta zbieracza","slot":"weapon"},"pistol":{"min":12,"max":18,"attacks":1,"accuracy":5,"crit":0,"pen":0,"category":"Palna 1R","scale":1.12,"critMultiplier":1.6,"bonus":{},"name":"Pistolet M-9","slot":"weapon"},"deserteagle":{"min":18,"max":27,"attacks":1,"accuracy":-3,"crit":2,"pen":1,"category":"Palna 1R","scale":1.12,"critMultiplier":1.6,"bonus":{},"name":"Pistolet pustynny","slot":"hand1"},"revolver":{"min":19,"max":28,"attacks":1,"accuracy":0,"crit":5,"pen":1,"category":"Palna 1R","scale":1.12,"critMultiplier":1.6,"bonus":{},"name":"Rewolwer Strażnika","slot":"weapon"},"smg":{"min":8,"max":13,"attacks":3,"accuracy":-7,"crit":-2,"pen":0,"category":"Palna 1R","scale":1.12,"critMultiplier":1.6,"bonus":{},"name":"Pistolet maszynowy Viper","slot":"weapon"},"rifle":{"min":18,"max":27,"attacks":1,"accuracy":2,"crit":0,"pen":1,"category":"Palna 2R","scale":0.93,"critMultiplier":1.8,"bonus":{"per":2},"name":"Karabin szabrownika","slot":"weapon"},"carbine":{"min":13,"max":20,"attacks":2,"accuracy":2,"crit":0,"pen":1,"category":"Palna 2R","scale":0.93,"critMultiplier":1.8,"bonus":{"per":1},"name":"Karabinek warty","slot":"weapon"},"shotgun":{"min":28,"max":42,"attacks":1,"accuracy":-7,"crit":1,"pen":1,"category":"Palna 2R","scale":0.93,"critMultiplier":1.8,"bonus":{"dex":-1},"name":"Strzelba pustkowi","slot":"weapon"},"sniper":{"min":36,"max":54,"attacks":1,"accuracy":5,"crit":5,"pen":4,"category":"Palna 2R","scale":0.93,"critMultiplier":1.8,"bonus":{"per":3},"name":"Karabin dalekiego zasięgu","slot":"weapon"},"lmg":{"min":13,"max":20,"attacks":3,"accuracy":-10,"crit":-2,"pen":1,"category":"Palna 2R","scale":0.93,"critMultiplier":1.8,"bonus":{"end":1},"name":"Karabin maszynowy PK","slot":"hand2"},"crossbow":{"min":18,"max":28,"attacks":1,"accuracy":1,"crit":4,"pen":3,"category":"Dystansowa 2R","scale":1.42,"critMultiplier":2.3,"bonus":{"per":2},"name":"Kusza tropiciela","slot":"weapon"},"harpoon":{"min":23,"max":36,"attacks":1,"accuracy":-3,"crit":3,"pen":4,"category":"Dystansowa 2R","scale":1.42,"critMultiplier":2.3,"bonus":{"per":2},"name":"Wyrzutnia harpunów","slot":"hand2"},"flame":{"min":12,"max":19,"attacks":3,"accuracy":-6,"crit":-3,"pen":2,"category":"Technologiczna 2R","scale":1.22,"critMultiplier":1.8,"bonus":{"int":2},"name":"Miotacz żaru","slot":"weapon"},"crowbar":{"min":15,"max":23,"attacks":1,"accuracy":-2,"crit":0,"pen":3,"category":"Biała 2R","scale":0.91,"critMultiplier":2.8,"bonus":{"str":1},"name":"Łom zbrojony","slot":"hand2"},"hammer":{"min":21,"max":33,"attacks":1,"accuracy":-4,"crit":2,"pen":2,"category":"Biała 2R","scale":0.91,"critMultiplier":2.8,"bonus":{"str":2,"dex":-1},"name":"Młot złomiarza","slot":"weapon"},"rail":{"min":31,"max":47,"attacks":1,"accuracy":3,"crit":3,"pen":6,"category":"Technologiczna 2R","scale":1.22,"critMultiplier":1.8,"bonus":{"int":3},"name":"Prototypowa broń szynowa","slot":"weapon"},"sledge":{"min":32,"max":50,"attacks":1,"accuracy":-6,"crit":4,"pen":3,"category":"Biała 2R","scale":0.91,"critMultiplier":2.8,"bonus":{"str":3,"dex":-1},"name":"Młot wyburzeniowy","slot":"hand2"}},"affixes":[{"id":"weapon_precise","name":"Precyzyjny","forms":{"m":"Precyzyjny","f":"Precyzyjna","p":"Precyzyjne"},"bonus":{"per":2},"accuracy":3,"on":"weapon","kind":"prefix","allowedWeapons":["baton","pipe","wrench","knife","cleaver","hatchet","saber","machete","pistol","deserteagle","revolver","smg","rifle","carbine","shotgun","sniper","lmg","crossbow","harpoon","flame","crowbar","hammer","rail","sledge"]},{"id":"weapon_brutal","name":"Brutalny","forms":{"m":"Brutalny","f":"Brutalna","p":"Brutalne"},"bonus":{"str":2},"damagePct":4,"on":"meleeWeapon","kind":"prefix","allowedWeapons":["baton","pipe","wrench","knife","cleaver","hatchet","saber","machete","crowbar","hammer","sledge"]},{"id":"weapon_destructive","name":"Niszczycielski","forms":{"m":"Niszczycielski","f":"Niszczycielska","p":"Niszczycielskie"},"damagePct":8,"on":"weapon","kind":"prefix","allowedWeapons":["baton","pipe","wrench","knife","cleaver","hatchet","saber","machete","pistol","deserteagle","revolver","smg","rifle","carbine","shotgun","sniper","lmg","crossbow","harpoon","flame","crowbar","hammer","rail","sledge"]},{"id":"weapon_lethal","name":"Zabójczy","forms":{"m":"Zabójczy","f":"Zabójcza","p":"Zabójcze"},"critPp":4,"on":"weapon","kind":"prefix","allowedWeapons":["baton","pipe","wrench","knife","cleaver","hatchet","saber","machete","pistol","deserteagle","revolver","smg","rifle","carbine","shotgun","sniper","lmg","crossbow","harpoon","flame","crowbar","hammer","rail","sledge"]},{"id":"weapon_quick","name":"Szybki","forms":{"m":"Szybki","f":"Szybka","p":"Szybkie"},"extraAttacks":1,"on":"lightWeapon","kind":"prefix","allowedWeapons":["baton","pipe","wrench","knife","cleaver","hatchet","saber","machete","pistol","revolver","smg"]},{"id":"weapon_stable","name":"Stabilny","forms":{"m":"Stabilny","f":"Stabilna","p":"Stabilne"},"accuracy":5,"critPp":2,"on":"weapon","kind":"prefix","allowedWeapons":["baton","pipe","wrench","knife","cleaver","hatchet","saber","machete","pistol","deserteagle","revolver","smg","rifle","carbine","shotgun","sniper","lmg","crossbow","harpoon","flame","crowbar","hammer","rail","sledge"]},{"id":"weapon_piercing","name":"Przebijający","forms":{"m":"Przebijający","f":"Przebijająca","p":"Przebijające"},"armorPen":4,"on":"weapon","kind":"prefix","allowedWeapons":["baton","pipe","wrench","knife","cleaver","hatchet","saber","machete","pistol","deserteagle","revolver","smg","rifle","carbine","shotgun","sniper","lmg","crossbow","harpoon","flame","crowbar","hammer","rail","sledge"]},{"id":"weapon_hunter","name":"Łowcy","bonus":{"per":2},"accuracy":2,"on":"weapon","kind":"suffix","allowedWeapons":["baton","pipe","wrench","knife","cleaver","hatchet","saber","machete","pistol","deserteagle","revolver","smg","rifle","carbine","shotgun","sniper","lmg","crossbow","harpoon","flame","crowbar","hammer","rail","sledge"]},{"id":"weapon_sniper","name":"Snajpera","bonus":{"per":2},"critPp":2,"on":"ranged","kind":"suffix","allowedWeapons":["pistol","deserteagle","revolver","smg","rifle","carbine","shotgun","sniper","lmg","crossbow","harpoon","flame","rail"]},{"id":"weapon_berserker","name":"Berserkera","damagePct":8,"accuracy":-4,"on":"weapon","kind":"suffix","allowedWeapons":["baton","pipe","wrench","knife","cleaver","hatchet","saber","machete","pistol","deserteagle","revolver","smg","rifle","carbine","shotgun","sniper","lmg","crossbow","harpoon","flame","crowbar","hammer","rail","sledge"]},{"id":"weapon_executioner","name":"Egzekutora","critPp":4,"on":"weapon","kind":"suffix","allowedWeapons":["baton","pipe","wrench","knife","cleaver","hatchet","saber","machete","pistol","deserteagle","revolver","smg","rifle","carbine","shotgun","sniper","lmg","crossbow","harpoon","flame","crowbar","hammer","rail","sledge"]},{"id":"weapon_warrior","name":"Wojownika","bonus":{"str":2},"damagePct":3,"on":"meleeWeapon","kind":"suffix","allowedWeapons":["baton","pipe","wrench","knife","cleaver","hatchet","saber","machete","crowbar","hammer","sledge"]},{"id":"weapon_destroyer","name":"Niszczyciela","damagePct":5,"armorPen":1,"on":"weapon","kind":"suffix","allowedWeapons":["baton","pipe","wrench","knife","cleaver","hatchet","saber","machete","pistol","deserteagle","revolver","smg","rifle","carbine","shotgun","sniper","lmg","crossbow","harpoon","flame","crowbar","hammer","rail","sledge"]},{"id":"weapon_piercer","name":"Penetratora","armorPen":5,"on":"weapon","kind":"suffix","allowedWeapons":["baton","pipe","wrench","knife","cleaver","hatchet","saber","machete","pistol","deserteagle","revolver","smg","rifle","carbine","shotgun","sniper","lmg","crossbow","harpoon","flame","crowbar","hammer","rail","sledge"]},{"id":"weapon_duelist","name":"Fechmistrza","critPp":3,"accuracy":3,"on":"oneHandWeapon","kind":"suffix","allowedWeapons":["baton","pipe","wrench","knife","cleaver","hatchet","saber","machete","pistol","deserteagle","revolver","smg"]}]}'::jsonb;
 w jsonb; a jsonb; v_id text; v_aff_id text; v_kind text; v_schema text;
 v_rarity int; v_upgrade int; v_mult numeric; v_factor numeric;
 v_damage numeric:=0; v_accuracy numeric:=0; v_crit numeric:=0;
 v_pen numeric:=0; v_extra numeric:=0; v_bonus jsonb;
 v_key text; v_val jsonb;
 v_workshop numeric[]:=array[0,.028,.056,.084,.112,.14];
begin
 if p_item is null or jsonb_typeof(p_item) is distinct from 'object' then
  raise exception 'Nieprawidłowy przedmiot'; end if;
 v_id:=p_item->>'id'; w:=c->'weapons'->v_id;
 if w is null then raise exception 'Nieznany model broni'; end if;
 v_schema:=coalesce(p_item->>'qualitySchema','legacy-v05');
 if v_schema not in ('legacy-v05','ashen-v06') then raise exception 'Nieznany schemat jakości'; end if;
 if (p_item->>'rarity') not in ('0','1','2','3','4') then raise exception 'Nieprawidłowa jakość'; end if;
 v_rarity:=(p_item->>'rarity')::int;
 if (p_item->>'upgrade') is null then v_upgrade:=0;
 elsif (p_item->>'upgrade') in ('0','1','2','3','4','5') then v_upgrade:=(p_item->>'upgrade')::int;
 else raise exception 'Nieprawidłowe ulepszenie'; end if;
 if v_schema='ashen-v06' and (p_item->>'quality') is distinct from
  (array['zwykly','rzadki','epicki','legendarny','mityczny'])[v_rarity+1] then
  raise exception 'Niespójna jakość'; end if;
 v_mult:=case when v_schema='ashen-v06'
   then (array[1,1.12,1.26,1.42,1.60]::numeric[])[v_rarity+1]
   else (array[1,1.14,1.32,1.58,1.95]::numeric[])[v_rarity+1] end;
 v_bonus:=coalesce(w->'bonus','{}'::jsonb);
 for v_kind in select unnest(array['prefix','suffix']) loop
  v_aff_id:=p_item->>v_kind;
  if v_aff_id is null or v_aff_id='' then continue; end if;
  select x.value into a from jsonb_array_elements(c->'affixes') x(value)
  where x.value->>'id'=v_aff_id and x.value->>'kind'=v_kind limit 1;
  if a is null or not (a->'allowedWeapons' ? v_id) then
   raise exception 'Niedozwolony prefiks/sufiks dla broni'; end if;
  v_damage:=v_damage+coalesce((a->>'damagePct')::numeric,0);
  v_accuracy:=v_accuracy+coalesce((a->>'accuracy')::numeric,0);
  v_crit:=v_crit+coalesce((a->>'critPp')::numeric,0);
  v_pen:=v_pen+coalesce((a->>'armorPen')::numeric,0);
  v_extra:=v_extra+coalesce((a->>'extraAttacks')::numeric,0);
  for v_key,v_val in select key,value from jsonb_each(coalesce(a->'bonus','{}'::jsonb)) loop
   v_bonus:=jsonb_set(v_bonus,array[v_key],to_jsonb(coalesce((v_bonus->>v_key)::numeric,0)+(v_val #>> '{}')::numeric),true);
  end loop;
 end loop;
 v_factor:=(w->>'scale')::numeric*v_mult*(1+v_damage/100)*(1+v_workshop[v_upgrade+1]);
 return jsonb_build_object('id',v_id,'qualitySchema',v_schema,'rarity',v_rarity,'upgrade',v_upgrade,
  'min',greatest(1,round((w->>'min')::numeric*v_factor)),
  'max',greatest(1,round((w->>'max')::numeric*v_factor)),
  'baseAttacks',(w->>'attacks')::int,'extraAttacks',v_extra,
  'accuracy',(w->>'accuracy')::numeric+v_accuracy,'critPp',(w->>'crit')::numeric+v_crit,
  'armorPen',(w->>'pen')::numeric+v_pen,
  'critMultiplier',(w->>'critMultiplier')::numeric,'bonus',v_bonus);
end;
$$;
